using System;

namespace ExpenseHub.Api.Contracts;

/// <summary>
/// Report request with its progress and, when finished, its result or error.
/// </summary>
/// <param name="Id">Report identifier generated by the server.</param>
/// <param name="Scope">Mine or Global.</param>
/// <param name="FromDate">First day of the period, inclusive.</param>
/// <param name="ToDate">Last day of the period, inclusive.</param>
/// <param name="Status">Pending, Processing, Completed or Failed.</param>
/// <param name="CreatedAt">Instant in UTC when the request was registered.</param>
/// <param name="StartedAt">Instant in UTC when processing started.</param>
/// <param name="CompletedAt">Instant in UTC when processing finished, successfully or not.</param>
/// <param name="Result">Result, only when the status is Completed.</param>
/// <param name="Error">Error, only when the status is Failed.</param>
public sealed record ReportResponse(
    Guid Id,
    string Scope,
    DateOnly FromDate,
    DateOnly ToDate,
    string Status,
    DateTime CreatedAt,
    DateTime? StartedAt,
    DateTime? CompletedAt,
    ReportResultResponse? Result,
    ReportErrorResponse? Error);
